class ParallelSmaRsiStrategies(QCAlgorithm):

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.add_equity(
                ticker, Resolution.DAILY, Market.USA, False
            ).symbol

        self.spy_closes = RollingWindow[float](101)
        self.aapl_closes = RollingWindow[float](15)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        self.aapl_red_streak = 0
        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def on_data(self, data: Slice):
        # Keep market-state quantities updating from every available bar.
        spy_bar = data.bars[self.symbols["SPY"]] if self.symbols["SPY"] in data.bars else None
        aapl_bar = data.bars[self.symbols["AAPL"]] if self.symbols["AAPL"] in data.bars else None

        if spy_bar is not None:
            self.spy_closes.add(float(spy_bar.close))

        if aapl_bar is not None:
            previous_aapl_close = self.aapl_closes[0] if self.aapl_closes.count > 0 else None
            current_aapl_close = float(aapl_bar.close)

            if previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif current_aapl_close < previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.aapl_closes.add(current_aapl_close)
            self.aapl_rsi.update(aapl_bar.end_time, aapl_bar.close)

        # Skip all rule evaluation unless every subscribed ticker has today's bar.
        if any(symbol not in data.bars for symbol in self.symbols.values()):
            return

        # Do not trade until every required indicator/window is fully formed.
        if not self.spy_closes.is_ready or not self.aapl_closes.is_ready or not self.aapl_rsi.is_ready:
            return

        spy_close_today = self.spy_closes[0]
        spy_close_yesterday = self.spy_closes[1]

        sma_today = sum(self.spy_closes[i] for i in range(100)) / 100.0
        sma_yesterday = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0

        spy_crosses_above = (
            spy_close_yesterday <= sma_yesterday and spy_close_today > sma_today
        )
        spy_crosses_below = (
            spy_close_yesterday >= sma_yesterday and spy_close_today < sma_today
        )

        # Strategy A
        if self.strategy_a_shares > 0:
            if spy_crosses_below:
                self.market_order(self.symbols["SPY"], -self.strategy_a_shares)
                self.strategy_a_shares = 0
        elif spy_crosses_above:
            quantity = int(
                math.floor(
                    0.40 * self.portfolio.total_portfolio_value / spy_close_today
                )
            )
            if quantity > 0:
                self.market_order(self.symbols["SPY"], quantity)
                self.strategy_a_shares = quantity

        # Strategy B
        if self.strategy_b_shares > 0:
            if self.aapl_rsi.current.value > 60:
                self.market_order(self.symbols["AAPL"], -self.strategy_b_shares)
                self.strategy_b_shares = 0
        elif self.aapl_red_streak >= 3:
            aapl_close = float(data.bars[self.symbols["AAPL"]].close)
            if self.portfolio.cash >= 20_000:
                quantity = int(math.floor(20_000 / aapl_close))
                if quantity > 0:
                    self.market_order(self.symbols["AAPL"], quantity)
                    self.strategy_b_shares = quantity
